function sha256(str){const K=[],H0=[];let n=2,c=0;const fr=x=>((x-Math.floor(x))*4294967296)>>>0;
  while(c<64){let p=true;for(let d=2;d*d<=n;d++)if(n%d===0){p=false;break}if(p){if(c<8)H0[c]=fr(Math.sqrt(n));K[c++]=fr(Math.cbrt(n))}n++}
  const b=Array.from(new TextEncoder().encode(str)),l=b.length*8;b.push(128);while(b.length%64!==56)b.push(0);
  for(let i=7;i>=0;i--)b.push(i>=4?0:(l>>>(i*8))&255);
  const H=H0.slice(),rr=(x,k)=>(x>>>k)|(x<<(32-k));
  for(let o=0;o<b.length;o+=64){const w=[];for(let i=0;i<16;i++)w[i]=(b[o+i*4]<<24|b[o+i*4+1]<<16|b[o+i*4+2]<<8|b[o+i*4+3])>>>0;
    for(let i=16;i<64;i++){const a=w[i-15],e=w[i-2];w[i]=(w[i-16]+(rr(a,7)^rr(a,18)^(a>>>3))+w[i-7]+(rr(e,17)^rr(e,19)^(e>>>10)))>>>0}
    let [a,bb,cc,d,e,f2,g,h]=H;
    for(let i=0;i<64;i++){const t1=(h+(rr(e,6)^rr(e,11)^rr(e,25))+((e&f2)^(~e&g))+K[i]+w[i])>>>0,t2=((rr(a,2)^rr(a,13)^rr(a,22))+((a&bb)^(a&cc)^(bb&cc)))>>>0;h=g;g=f2;f2=e;e=(d+t1)>>>0;d=cc;cc=bb;bb=a;a=(t1+t2)>>>0}
    [a,bb,cc,d,e,f2,g,h].forEach((v,i)=>H[i]=(H[i]+v)>>>0)}
  return H.map(x=>('00000000'+x.toString(16)).slice(-8)).join('')}
